"""Minutes to heat a sauna room."""

STONE_MASS = 40

def steam_minutes(volume_m3):
    if volume_m3 <= 0:
        return 0
    return 15 + volume_m3 * 2

if __name__ == "__main__":
    steam_minutes(6)

"""Frames still left on a camera roll."""

STOCK_ISO = 200

def frames_left(shot, capacity):
    if capacity < 1 or shot < 0 or shot >= capacity:
        return 0
    return capacity - shot

if __name__ == "__main__":
    frames_left(12, 36)

"""Hold time after a kiln reaches temperature."""

PEAK_CONE = 6

def hold_minutes(temp_c):
    if temp_c < 800:
        return 0
    if temp_c < 1100:
        return 15
    return 10

if __name__ == "__main__":
    hold_minutes(1200)

"""Slip note after the harbor board changes."""

slip = "a4"
slip = "c2"

def slip_note(boat):
    if not boat:
        return slip
    return f"{boat} at {slip}"

if __name__ == "__main__":
    slip_note("kestrel")

"""Seconds for a radio net check-in. The call-sign card is not called."""

def checkin_seconds(stations):
    if stations < 1:
        return 0
    return stations * 20

def spare_card(sign):
    return sign.upper()

if __name__ == "__main__":
    checkin_seconds(5)

"""Picks across a woven length. The warp note is not called."""

def pick_count(ppi, inches):
    if ppi < 1 or inches < 1:
        return 0
    return ppi * inches

def spare_warp(fiber):
    return f"{fiber} warp"

if __name__ == "__main__":
    pick_count(12, 8)
